6	function validateJsonValue(value, fieldName) {
7	    if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
8	    if (typeof value === 'number' && Number.isFinite(value)) return value;
9	    if (Array.isArray(value)) return value.map((entry, index) => validateJsonValue(entry, `${fieldName}[${index}]`));
10	    if (!value || typeof value !== 'object') throw new Error(`Invalid ${fieldName}`);
11	
12	    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, validateJsonValue(entry, `${fieldName}.${key}`)]));
13	}
14	
15	/** Validate one conversation-owned for-each configuration. */
16	export function validateForEachConfig(value, fieldName = 'forEach') {
17	    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(`Invalid ${fieldName}`);
18	    const allowedFields = new Set(['dataPath', 'failurePolicy', 'fileName', 'mode', 'startIndex', 'value']);
19	    const unsupportedField = Object.keys(value).find((name) => !allowedFields.has(name));
20	    if (unsupportedField) throw new Error(`Unsupported ${fieldName} field: ${unsupportedField}`);
21	    if (value.dataPath !== undefined && typeof value.dataPath !== 'string') throw new Error(`Invalid ${fieldName}.dataPath`);
22	    if (typeof value.fileName !== 'string' || value.fileName.length === 0) throw new Error(`Invalid ${fieldName}.fileName`);
23	    if (!FOR_EACH_MODES.has(value.mode)) throw new Error(`Invalid ${fieldName}.mode`);
24	    if (!FOR_EACH_FAILURE_POLICIES.has(value.failurePolicy)) throw new Error(`Invalid ${fieldName}.failurePolicy`);
25	    const startIndex = value.startIndex === undefined ? 0 : value.startIndex;
26	    if (typeof startIndex !== 'number' || !Number.isSafeInteger(startIndex) || startIndex < 0) {
27	        throw new Error(`Invalid ${fieldName}.startIndex`);
28	    }
29	
30	    return {
31	        ...(value.dataPath !== undefined ? { dataPath: value.dataPath } : {}),
32	        failurePolicy: value.failurePolicy,
33	        fileName: value.fileName,
34	        mode: value.mode,
35	        startIndex,
36	        value: validateJsonValue(value.value, `${fieldName}.value`),
37	    };
38	}
