40	function dataPathValue(record, path) {
41	    const segments = path.split('.');
42	    if (segments.some((segment) => segment.length === 0)) throw new Error(`Missing for-each data path: ${path}`);
43	    let current = record;
44	    for (const segment of segments) {
45	        if (Array.isArray(current)) {
46	            if (!/^\d+$/u.test(segment)) throw new Error(`Missing for-each data path: ${path}`);
47	            const index = Number(segment);
48	            if (!Number.isSafeInteger(index) || index >= current.length) throw new Error(`Missing for-each data path: ${path}`);
49	            current = current[index];
50	            continue;
51	        }
52	        if (!current || typeof current !== 'object' || !Object.hasOwn(current, segment)) {
53	            throw new Error(`Missing for-each data path: ${path}`);
54	        }
55	        current = current[segment];
56	    }
57	
58	    return current;
59	}
60	
61	/**
62	 * Ordered loop records for one JSON root: a root array iterates directly, a selector picks an array
63	 * inside any other root, and without a selector the root is one record.
64	 */
65	export function forEachRecords(value, dataPath = '') {
66	    if (Array.isArray(value)) return [...value];
67	    const path = dataPath.trim();
68	    if (path.length === 0) return [value];
69	    const selected = dataPathValue(value, path);
70	    if (!Array.isArray(selected)) throw new Error(`For-each data path is not a list: ${path}`);
71	
72	    return [...selected];
73	}
