75	/** Resolve data placeholders against one record. Strings remain raw; other JSON values serialize. */
76	export function resolveDataPlaceholders(text, record) {
77	    return text.replace(DATA_PLACEHOLDER_PATTERN, (_match, path) => {
78	        const value = dataPathValue(record, path.trim());
79	
80	        return typeof value === 'string' ? value : JSON.stringify(value);
81	    });
82	}
