23	/** Shows supported placeholders at the caret after the user types `{{`. */
24	export function MarkdownPlaceholderTypeaheadPlugin() {
25	    const [editor] = useLexicalComposerContext();
26	    const { overlayContainer, placeholders } = useCellValue(markdownPlaceholderConfig$)
27	    const [query, setQuery] = useState('')
28	    const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null)
29	    const options = useMemo(
30	        () => placeholders
31	            .filter((placeholder) => placeholderMatchesQuery(placeholder, query))
32	            .map((placeholder) => new MarkdownPlaceholderOption(placeholder)),
33	        [placeholders, query],
34	    )
35	
36	    const triggerFn = useCallback<TriggerFn>((text, editor) => {
37	        const match = matchPlaceholderTrigger(text, editor)
38	        if (!match || !placeholders.some((placeholder) => placeholderMatchesQuery(placeholder, match.matchingString))) return null
39	
40	        return match
41	    }, [placeholders])
42	
43	    const handleQueryChange = useCallback((nextQuery: string | null) => {
44	        setQuery(nextQuery ?? '')
45	    }, [])
46	
47	    const handleOpen = useCallback((resolution: MenuResolution) => {
48	        setAnchorRect(resolution.getRect())
49	    }, [])
50	
51	    const handleClose = useCallback(() => {
52	        setAnchorRect(null)
53	    }, [])
54	
55	    const handleDraftReset = useCallback(() => {
56	        setAnchorRect(null);
57	        setQuery('');
58	        return false;
59	    }, []);
60	    useEffect(() => editor.registerCommand(RESET_MARKDOWN_DRAFT_COMMAND, handleDraftReset, COMMAND_PRIORITY_HIGH),
61	        [editor, handleDraftReset]);
62	
63	    const handleSelectOption = useCallback((
64	        option: MarkdownPlaceholderOption,
65	        textNodeContainingQuery: TextNode | null,
66	        closeMenu: () => void,
67	    ) => {
68	        if (!textNodeContainingQuery) return
69	
70	        const placeholderText = formatActionPlaceholder(option.placeholder.name)
71	        textNodeContainingQuery.setTextContent(placeholderText)
72	        if (option.placeholder.name === 'data') textNodeContainingQuery.select(7, 11)
73	        else textNodeContainingQuery.selectEnd()
74	        closeMenu()
75	    }, [])
76	
77	    const renderMenu = useCallback<MenuRenderFn<MarkdownPlaceholderOption>>((anchorElementRef, itemProps) => {
78	        if (!anchorElementRef.current || !anchorRect || itemProps.options.length === 0) return null
79	
80	        return (
81	            <MarkdownPlaceholderMenu
82	                anchorRect={anchorRect}
83	                onHighlight={itemProps.setHighlightedIndex}
84	                onSelect={itemProps.selectOptionAndCleanUp}
85	                options={itemProps.options}
86	                selectedIndex={itemProps.selectedIndex}
87	            />
88	        )
89	    }, [anchorRect])
90	
91	    return (
92	        <LexicalTypeaheadMenuPlugin<MarkdownPlaceholderOption>
93	            menuRenderFn={renderMenu}
94	            onClose={handleClose}
95	            onOpen={handleOpen}
96	            onQueryChange={handleQueryChange}
97	            onSelectOption={handleSelectOption}
98	            options={options}
99	            parent={overlayContainer ?? undefined}
100	            triggerFn={triggerFn}
101	        />
102	    )
103	}
